  static bool Finite(double n) { return !double.IsNaN(n)&&!double.IsInfinity(n); }
  public static void ValidateCrop(Clip c,Media m){
   var sides=new[]{c.CropLeft,c.CropTop,c.CropRight,c.CropBottom};
   if(sides.Any(n=>!Finite(n)||n<0||n>=1)||c.CropLeft+c.CropRight>=1||c.CropTop+c.CropBottom>=1)throw new InvalidDataException("Invalid crop boundaries");
