   if(cropped&&(!string.IsNullOrEmpty(c.Text)||m==null||m.Kind=="audio"||m.Width<1||m.Height<1))throw new InvalidDataException("Crop requires an image or video with known dimensions");
   if(cropped&&(m.Width-(int)Math.Round(c.CropLeft*m.Width)-(int)Math.Round(c.CropRight*m.Width)<1||m.Height-(int)Math.Round(c.CropTop*m.Height)-(int)Math.Round(c.CropBottom*m.Height)<1))throw new InvalidDataException("Crop must retain at least one source pixel");
  }
  static string Tempo(double speed) { var s=new StringBuilder();while(speed<.5){s.Append(",atempo=0.5");speed*=2;}while(speed>2){s.Append(",atempo=2");speed/=2;}s.Append(",atempo="+N(speed));return s.ToString(); }
  public static void Validate(Project p,bool checkFiles) {
