   if(p.Width<2||p.Height<2||p.Width>8192||p.Height>8192||p.Width%2!=0||p.Height%2!=0||p.Fps<1||p.Fps>120||p.TrackCount<1||p.TrackCount>64)throw new InvalidDataException("Invalid project dimensions, frame rate or tracks");
