  public static double Length(Project p){double clips=p.Clips.Count==0?0:p.Clips.Max(c=>c.Start+c.Duration);return p.Markers==null||p.Markers.Count==0?clips:Math.Max(clips,p.Markers.Max(m=>m.Time));}
