  public static void CancelRender(){lock(renderLock){renderCanceled=true;if(activeRender!=null)try{if(!activeRender.HasExited)activeRender.Kill();}catch{}}}
  static void RunRender(string args,double end,Action<string> progress){
   var p=new Process{StartInfo=new ProcessStartInfo(Tool("ffmpeg"),args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}};var err=new StringBuilder();p.ErrorDataReceived+=(o,e)=>{if(e.Data!=null)lock(err){err.AppendLine(e.Data);if(err.Length>30000)err.Remove(0,err.Length-30000);}};
