  static bool IsTransientSaveError(IOException error){return error.HResult==unchecked((int)0x80070020)||error.HResult==unchecked((int)0x80070021)||error.HResult==unchecked((int)0x80070497);}
  public static void Save(Project p,string path) {
   Validate(p,false);path=System.IO.Path.GetFullPath(path);
   if(p.Media.Any(m=>string.Equals(System.IO.Path.GetFullPath(m.Path),path,StringComparison.OrdinalIgnoreCase)))throw new InvalidDataException("Project save cannot overwrite source media");
   string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";
   try{
    File.WriteAllText(temp,new JavaScriptSerializer().Serialize(p),new UTF8Encoding(false));
    for(int attempt=0;;attempt++){
     try{if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);break;}
     catch(IOException error){if(attempt>=4||!IsTransientSaveError(error))throw;System.Threading.Thread.Sleep(100<<attempt);}
    }
   }finally{if(File.Exists(temp))File.Delete(temp);}
  }
