  static double Rms(string file,string dir) {string raw=System.IO.Path.Combine(dir,"audio.pcm");Engine.Run("ffmpeg","-y -v error -i "+Engine.Quote(file)+" -vn -ac 1 -ar 48000 -f s16le "+Engine.Quote(raw));byte[] b=File.ReadAllBytes(raw);double sum=0;for(int i=0;i+1<b.Length;i+=2){double v=BitConverter.ToInt16(b,i)/32768.0;sum+=v*v;}return Math.Sqrt(sum/(b.Length/2));}
  static void Require(bool b,string message){if(!b)throw new Exception(message);}
  static double Brightness(byte[] b) {return b.Select(v=>(double)v).Sum();}
